const now = new Date();
const madridOptions = { timeZone: 'Europe/Madrid' };

const year = now.toLocaleString('en-CA', { ...madridOptions, year: 'numeric' });
const month = now.toLocaleString('en-CA', { ...madridOptions, month: '2-digit' });
const day = now.toLocaleString('en-CA', { ...madridOptions, day: '2-digit' });
const fechaIso = `${year}-${month}-${day}`;

const madridTime = now.toLocaleTimeString('es-ES', { ...madridOptions, hour: '2-digit', minute: '2-digit' });

const dayNum = new Date(now.toLocaleString('en-US', madridOptions)).getDay();
const dayNames = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];

return `Fecha actual: ${fechaIso} (${dayNames[dayNum]}). Hora: ${madridTime}. Es fin de semana: ${dayNum === 0 || dayNum === 6 ? 'sí' : 'no'}.`;

let fecha, hora;

// Intentar parsear como JSON primero
try {
  const parsed = JSON.parse(query);
  fecha = parsed.fecha;
  hora = parsed.hora;
} catch (e) {
  // Si no es JSON, intentar con regex
  const fechaMatch = query.match(/fecha[=:\s]["']?(\d{4}-\d{2}-\d{2})["']?/i);
  const horaMatch = query.match(/hora[=:\s]["']?(\d{1,2}:\d{2})["']?/i);
  fecha = fechaMatch ? fechaMatch[1] : null;
  hora = horaMatch ? horaMatch[1] : null;
}

if (!fecha || !hora) {
  return `Error: No pude extraer fecha/hora de: "${query}". Necesito fecha y hora.`;
}

const [year, month, day] = fecha.split('-').map(Number);
const [hourNum, minuteNum] = hora.split(':').map(Number);

const requestedDate = new Date(year, month - 1, day, hourNum, minuteNum);
const now = new Date();

const dayOfWeek = requestedDate.getDay();
if (dayOfWeek === 0 || dayOfWeek === 6) {
  return `No disponible: ${fecha} es fin de semana. Solo de lunes a viernes.`;
}

if (requestedDate < now) {
  return `No disponible: ${fecha} es fecha pasada.`;
}

const minTime = new Date(now.getTime() + 24 * 60 * 60 * 1000);
if (requestedDate < minTime) {
  return 'No disponible: Se necesitan al menos 24 horas de antelación.';
}

const isMorningValid = (hourNum >= 10 && hourNum < 13) || (hourNum === 13 && minuteNum === 0);
const isAfternoonValid = (hourNum >= 16 && hourNum < 17) || (hourNum === 17 && minuteNum === 0);

if (!isMorningValid && !isAfternoonValid) {
  return `No disponible: ${hora} no es horario válido. Mañanas: 10:00-13:00. Tardes: 16:00-17:00.`;
}

return `DISPONIBLE: El ${fecha} a las ${hora} está libre para agendar con Elena.`;
